const update = (partial: Partial<DictionaryPopupSettings>) => {
  onChange({ ...settings, ...partial });
};
// settings has defaultActiveTabPerLang: { en: 'audio' }
// partial sets defaultActiveTab: 'image'
// result still carries { en: 'audio' } → popup opens audio for en

cases.good:
const update = (partial: Partial<DictionaryPopupSettings>) => {
  const next: DictionaryPopupSettings = {
    ...DEFAULT_DICTIONARY_POPUP_SETTINGS,
    ...settings,
    ...partial,
    defaultActiveTabPerLang: 'defaultActiveTab' in partial ? undefined : settings.defaultActiveTabPerLang,
  };
  onChange(next);
};
// defaults fill missing optional fields (tts), and stale per-lang override is cleared
// when the user changes the global defaultActiveTab
